#!/usr/bin/env python3
"""
Comprehensive tests for the calc.py calculator module.

Tests cover:
- Basic arithmetic operations (add, subtract, multiply, divide)
- Edge cases (division by zero, invalid inputs)
- Input parsing and validation
- CLI argument handling
- The calculate dispatcher function
"""
import pytest
import sys
from unittest.mock import patch

# Import the module under test
import calc


# =============================================================================
# Fixtures
# =============================================================================

@pytest.fixture
def sample_numbers():
    """Provide sample numbers for testing."""
    return {
        'positive': (10.0, 5.0),
        'negative': (-10.0, -5.0),
        'mixed': (-10.0, 5.0),
        'zeros': (0.0, 0.0),
        'floats': (3.14, 2.71),
        'large': (1e10, 1e5),
    }


@pytest.fixture
def mock_argv():
    """Factory fixture to mock sys.argv for CLI tests."""
    def _mock_argv(args):
        return patch.object(sys, 'argv', ['calc.py'] + args)
    return _mock_argv


# =============================================================================
# Tests for add function
# =============================================================================

class TestAdd:
    """Tests for the add function."""

    @pytest.mark.parametrize("a, b, expected", [
        (2, 3, 5),
        (0, 0, 0),
        (-1, 1, 0),
        (-5, -3, -8),
        (1.5, 2.5, 4.0),
        (1e10, 1e10, 2e10),
    ])
    def test_add_various_inputs(self, a, b, expected):
        """Test addition with various input combinations."""
        assert calc.add(a, b) == expected

    def test_add_commutative(self, sample_numbers):
        """Test that addition is commutative."""
        a, b = sample_numbers['positive']
        assert calc.add(a, b) == calc.add(b, a)

    def test_add_identity(self):
        """Test adding zero (identity element)."""
        assert calc.add(42, 0) == 42
        assert calc.add(0, 42) == 42


# =============================================================================
# Tests for subtract function
# =============================================================================

class TestSubtract:
    """Tests for the subtract function."""

    @pytest.mark.parametrize("a, b, expected", [
        (5, 3, 2),
        (0, 0, 0),
        (-1, 1, -2),
        (-5, -3, -2),
        (10.5, 2.5, 8.0),
        (3, 5, -2),
    ])
    def test_subtract_various_inputs(self, a, b, expected):
        """Test subtraction with various input combinations."""
        assert calc.subtract(a, b) == expected

    def test_subtract_self(self):
        """Test subtracting a number from itself."""
        assert calc.subtract(100, 100) == 0

    def test_subtract_identity(self):
        """Test subtracting zero (identity element)."""
        assert calc.subtract(42, 0) == 42


# =============================================================================
# Tests for multiply function
# =============================================================================

class TestMultiply:
    """Tests for the multiply function."""

    @pytest.mark.parametrize("a, b, expected", [
        (2, 3, 6),
        (0, 100, 0),
        (-1, 1, -1),
        (-5, -3, 15),
        (1.5, 2, 3.0),
        (1, 1, 1),
    ])
    def test_multiply_various_inputs(self, a, b, expected):
        """Test multiplication with various input combinations."""
        assert calc.multiply(a, b) == expected

    def test_multiply_commutative(self, sample_numbers):
        """Test that multiplication is commutative."""
        a, b = sample_numbers['positive']
        assert calc.multiply(a, b) == calc.multiply(b, a)

    def test_multiply_by_zero(self):
        """Test multiplying by zero."""
        assert calc.multiply(999999, 0) == 0
        assert calc.multiply(0, 999999) == 0

    def test_multiply_identity(self):
        """Test multiplying by one (identity element)."""
        assert calc.multiply(42, 1) == 42
        assert calc.multiply(1, 42) == 42


# =============================================================================
# Tests for divide function
# =============================================================================

class TestDivide:
    """Tests for the divide function."""

    @pytest.mark.parametrize("a, b, expected", [
        (6, 3, 2.0),
        (10, 4, 2.5),
        (-10, 2, -5.0),
        (-10, -2, 5.0),
        (0, 5, 0.0),
        (1, 3, pytest.approx(0.333333, rel=1e-4)),
    ])
    def test_divide_various_inputs(self, a, b, expected):
        """Test division with various input combinations."""
        assert calc.divide(a, b) == expected

    def test_divide_by_zero_raises_error(self):
        """Test that division by zero raises ZeroDivisionError."""
        with pytest.raises(ZeroDivisionError) as exc_info:
            calc.divide(10, 0)
        assert "Cannot divide by zero" in str(exc_info.value)

    def test_divide_zero_by_zero_raises_error(self):
        """Test that 0/0 raises ZeroDivisionError."""
        with pytest.raises(ZeroDivisionError):
            calc.divide(0, 0)

    def test_divide_identity(self):
        """Test dividing by one (identity element)."""
        assert calc.divide(42, 1) == 42.0

    def test_divide_self(self):
        """Test dividing a number by itself."""
        assert calc.divide(100, 100) == 1.0


