class TestCalculate:
    """Tests for the calculate dispatcher function."""

    @pytest.mark.parametrize("num1, op, num2, expected", [
        (5, '+', 3, 8),
        (5, '-', 3, 2),
        (5, '*', 3, 15),
        (5, 'x', 3, 15),  # Alternative multiplication operator
        (6, '/', 3, 2.0),
    ])
    def test_calculate_all_operators(self, num1, op, num2, expected):
        """Test calculate with all valid operators."""
        assert calc.calculate(num1, op, num2) == expected

