        """Test calculate with invalid operator raises ValueError."""
        with pytest.raises(ValueError) as exc_info:
            calc.calculate(5, '%', 3)
        assert "Invalid operator" in str(exc_info.value)
        assert "%" in str(exc_info.value)

    def test_calculate_division_by_zero(self):
        """Test calculate propagates ZeroDivisionError."""
        with pytest.raises(ZeroDivisionError):
            calc.calculate(10, '/', 0)

    @pytest.mark.parametrize("invalid_op", ['^', '**', '//', 'add', '', ' '])
    def test_calculate_various_invalid_operators(self, invalid_op):
        """Test that various invalid operators are rejected."""
        with pytest.raises(ValueError) as exc_info:
            calc.calculate(1, invalid_op, 2)
        assert "Invalid operator" in str(exc_info.value)


