    @pytest.mark.parametrize("value, expected", [
        ('42', 42.0),
        ('3.14', 3.14),
        ('-100', -100.0),
        ('0', 0.0),
        ('1e10', 1e10),
        ('-2.5', -2.5),
        ('  123  ', 123.0),  # Whitespace should be handled by float()
    ])
    def test_parse_valid_numbers(self, value, expected):
        """Test parsing valid number strings."""
        assert calc.parse_number(value) == expected

    @pytest.mark.parametrize("invalid_value", [
        'abc',
        '',
        'twelve',
        '1.2.3',
        '10+5',
        'NaN',  # Note: 'nan' might be valid in some Python versions
    ])
    def test_parse_invalid_numbers(self, invalid_value):
        """Test parsing invalid values raises ValueError."""
        # Skip 'NaN' if it's actually valid
        if invalid_value.lower() == 'nan':
            try:
                result = calc.parse_number(invalid_value)
                # If it parses, it should be nan
                import math
                assert math.isnan(result)
                return
            except ValueError:
                pass  # Expected behavior

        with pytest.raises(ValueError) as exc_info:
            calc.parse_number(invalid_value)
        assert "Invalid number" in str(exc_info.value)


